const langOf = (hass) => (hass && hass.language || "en").slice(0, 2);
// a state text of the device (mode, drying, option) in the language of HA, whatever the device's language
function locState(hass, v) {
  if (!v) return v;
  const lk = /^(.*) · (\w+)$/.exec(v);                  // "Learning 3/12 · fan_minus" – translate the key too
  if (lk && /\d+\/\d+$/.test(lk[1])) { const k = tr(hass)["key_" + lk[2]]; return `${locState(hass, lk[1])} · ${k || lk[2]}`; }
  const m = /^(.*) (\d+\/\d+)$/.exec(v);            // "Calibrating 4/10" – translate the text, keep the progress
  if (m) { const t = locState(hass, m[1]); if (t !== m[1]) return `${t} ${m[2]}`; }
  const l = langOf(hass);
  for (const k in STATES) { const m = STATES[k]; if (Object.values(m).includes(v)) return m[l] || m.en || v; }
  return v;
}

