class HbhCard extends HTMLElement {
  static getConfigElement() { return document.createElement("hbh-card-editor"); }
  static getStubConfig() { return {}; }
  setConfig(config) { this._config = config || {}; this._sig = null; if (this._hass) this._render(); }
  getCardSize() { return 9; }

  connectedCallback() { this._tick = setInterval(() => this._render(), 5000); }
  disconnectedCallback() { clearInterval(this._tick); }

  set hass(hass) {
    this._hass = hass;
    if (!this._idx || this._idxAt !== Object.keys(hass.entities || {}).length) {
      this._idx = findIndex(hass, this._config && this._config.device);
      this._idxAt = Object.keys(hass.entities || {}).length;
    }
    this._render();
  }

  _st(key) { const id = this._idx && this._idx.ids[key]; return id ? this._hass.states[id] : undefined; }
  _v(key) { const s = this._st(key); return s ? s.state : undefined; }
  _num(key) { const v = parseFloat(this._v(key)); return isNaN(v) ? NaN : v; }
  _src(key) { const v = this._v(key); return v && v.includes(".") ? v : null; }

  _render() {
    const hass = this._hass; if (!hass || !this._config) return;
    if (!this.shadowRoot) {
      this.attachShadow({ mode: "open" });
      this.shadowRoot.addEventListener("click", (e) => this._click(e));
    }
    const idx = this._idx;
    const T = tr(hass);
    // re-render only when something shown changed
    const watch = idx ? Object.values(idx.ids).concat(SOURCES.map((k) => this._src(k)).filter(Boolean)) : [];
    // the press recognised by the hood ESP (knows learned codes); older firmware: the receiver directly
    const rxSt = idx && (this._st("remote_key") && this._st("remote_key").state !== "unknown" ? this._st("remote_key") : hass.states[this._src("src_remote")]);
    const rx = parseRemote(rxSt);
    const rxPulse = rx && rx.age < 6 ? rx.pulse : null;
    const rxBucket = rx ? (rx.age < 6 ? "p" : ago(T, rx.age)) : "";
    const sig = rxBucket + "|" + (idx ? idx.device : "-") + "|" + watch.map((id) => { const s = hass.states[id]; return s ? s.state + (s.attributes.options || "") : "?"; }).join("|") + hass.language;
    if (sig === this._sig) return;
    this._sig = sig;

    const title = this._config.title || T.title;
    let rxHtml = "";
    if (rxSt) {
      const off = !rx && (rxSt.state === "unavailable");
      const txt = off ? T.rx_off : rx ? `${T.rx[rx.label] || rx.label} · ${ago(T, rx.age)}` : "";
      if (txt) rxHtml = `<span class="rx ${off ? "off" : rx && rx.age < 60 ? "fresh" : ""}" data-more="src:src_remote" title="${esc(T.rx_title)}">` +
                        `<ha-icon icon="${off ? "mdi:remote-off" : "mdi:remote"}"></ha-icon>${esc(txt)}</span>`;
    }
    let h = `<style>${CSS}</style><ha-card><div class="hd"><ha-icon icon="mdi:stove"></ha-icon>${esc(title)}${rxHtml}</div>`;
    if (!idx) { this.shadowRoot.innerHTML = h + `<div class="nf">${T.not_found}</div></ha-card>`; return; }

    const speed = this._num("speed"), lightOn = this._v("light_on") === "on", bright = this._num("brightness");
    const tSpeed = this._num("target_speed"), tBright = this._num("target_brightness");
    const busy = this._v("busy") === "on";
    const hoodP = parseFloat((hass.states[this._src("src_hood_power")] || {}).state);
    const hobP = parseFloat((hass.states[this._src("src_hob_power")] || {}).state);
    const relay = this._src("src_hood_switch") && hass.states[this._src("src_hood_switch")];
    const relayOn = relay ? relay.state === "on" : true;
    const colourSt = this._st("colour"), colourIdx = colourSt ? (colourSt.attributes.options || []).indexOf(colourSt.state) : -1;
    const left = this._num("timer_left");

    // timer bar
    if (left > 0) {
      const pct = Math.max(0, Math.min(100, (left / 600) * 100));
      h += `<div class="bar" data-more="timer_left"><div class="f" style="width:${pct}%"></div><div class="x">⏱ ${T.timer_left} ${mmss(left)}</div></div>`;
    }
    if (this._v("alarm") === "on") h += `<div class="warn" data-more="alarm">🔥 ${T.alarm}</div>`;
    if (this._v("rf_problem") === "on") h += `<div class="warn" data-more="rf_problem">⚠ ${T.rf_problem}</div>`;
    const calSt = this._v("cal_state") || "";
    if (/\d+\/10$/.test(calSt)) h += `<div class="warn" data-more="cal_state" style="border-color:var(--ch-purple);background:color-mix(in srgb, var(--ch-purple) 15%, transparent)">⚙ ${esc(locState(hass, calSt))} · ${T.calibrate_hint}</div>`;
    // learning wizard: "Learning 3/12 · fan_minus" – progress and the key to press (keys of the hood profile)
    const lrnSt = this._v("lrn_state") || "", lm = /(\d+)\/(\d+)(?: · (\w+))?$/.exec(lrnSt);
    if (lm) {
      const s = +lm[1] - 1, nk = Math.round(+lm[2] / 2), k = lm[3] || LEARN_KEYS[Math.floor(s / 2)] || LEARN_KEYS[0];
      h += `<div class="warn lrn" data-more="lrn_state"><div>📡 ${T.learn_press}: <b>${esc(T["key_" + k] || k)}</b> (${s % 2 ? T.learn_again : T.learn_twice})</div>` +
        `<div class="lrn2"><span>${Math.floor(s / 2) + 1}/${nk} · ${T.learn_hint}</span><span class="lx" data-act="learn_cancel">${T.learn_cancel}</span></div></div>`;
    }
    if (this._v("filter_due") === "on") h += `<div class="warn" data-more="filter_usage">🧽 ${T.filter_due} · ${dec(this._num("filter_usage"), 0)} %</div>`;

    // hob + hood
    const cooking = this._v("cooking") === "on", hobOn = this._v("hob_on") === "on";
    const kwhToday = this._num("energy_today");
    const hobTxt = (cooking ? T.cooking : hobOn ? T.on : T.off) + (isNaN(kwhToday) ? "" : ` · ${T.today} ${dec(kwhToday, 2)} kWh`);
    // discreet current power of the hob in the label (source entity; 2-min average when the source is missing)
    const hobW = Math.max(0, isNaN(hobP) ? this._num("hob_avg") : hobP);   // 3-phase meters read a few W below 0 when idle
    let hobLbl = isNaN(hobW) ? T.hob : `${T.hob} · ${fmtW(hobW)}`;
    const recNow = this._num("recommended"), prof = this._v("profile");
    if (cooking && recNow >= 0 && prof) hobLbl += ` · ${prof} → ${recNow === 4 ? T.boost.toLowerCase() : fill(T.wants, { n: recNow })}`;
    const hobCol = cooking ? "var(--ch-orange)" : hobOn ? "var(--ch-yellow)" : "var(--ch-dim)";
    const mode = locState(hass, this._v("mode") || "");
    const hoodCol = speed > 0 ? "var(--ch-teal)" : "var(--ch-dim)";
    const hoodTxt = (speed === 4 ? T.boost : speed > 0 ? `${T.speed} ${speed}` : T.stopped).toLowerCase() + (lightOn ? ` · ${T.light_short}` : "");
    h += `<div class="grid g2">
      ${tile({ icon: cooking ? "mdi:stove" : "mdi:stove", col: hobCol, v: hobTxt, l: hobLbl, more: this._src("src_hob_power") ? "src:src_hob_power" : "cooking" })}
      ${tile({ icon: speed > 0 ? "mdi:fan" : "mdi:fan-off", col: hoodCol, v: hoodTxt, l: mode ? `${T.hood} · ${mode}` : T.hood, more: "mode" })}
    </div>`;

    // light
    const lightTxt = lightOn ? `${T.light_on} · ${isNaN(bright) ? "" : bright + " % · "}${fmtW(hoodP)}` : `${T.light_off} · ${fmtW(hoodP)}`;
    h += `<div class="grid">${tile({ big: true, icon: lightOn ? "mdi:lightbulb-on" : "mdi:lightbulb-outline", col: lightOn ? "var(--ch-yellow)" : "var(--ch-dim)", v: lightTxt, l: T.light, more: "light", rx: rxPulse === "light" })}</div>`;
    h += `<div class="grid g2">
      ${tile({ btn: true, icon: "mdi:lightbulb-on", col: "var(--ch-yellow)", v: T.light_on_btn, act: "light_on", dis: lightOn })}
      ${tile({ btn: true, icon: "mdi:lightbulb-off", col: "var(--ch-dim)", v: T.light_off_btn, act: "light_off", dis: !lightOn })}
    </div><div class="grid g4">`;
    [25, 50, 75, 100].forEach((p, i) => {
      h += tile({ btn: true, icon: `mdi:lightbulb${p === 100 ? "-on" : ""}`, col: "var(--ch-yellow)", v: p + " %", act: "bright:" + (i + 1),
                  on: lightOn && bright === p, tgt: busy && tBright === p && !(lightOn && bright === p),
                  rx: rxPulse === "bright" && (bright === p || !lightOn) });
    });
    h += `</div><div class="grid g2">
      ${tile({ btn: true, icon: "mdi:fire", col: "var(--ch-orange)", v: T.warmer, act: "colour:1", on: lightOn && colourIdx === 1, dis: !lightOn, rx: rxPulse === "colour:1" })}
      ${tile({ btn: true, icon: "mdi:snowflake", col: "var(--ch-teal)", v: T.cooler, act: "colour:0", on: lightOn && colourIdx === 0, dis: !lightOn, rx: rxPulse === "colour:0" })}
    </div>`;

    // fan
    const rec = this._num("recommended");
    const fanTxt = speed === 4 ? T.boost : speed > 0 ? `${T.speed} ${speed}` : T.stopped;
    h += `<div class="grid">${tile({ big: true, icon: speed > 0 ? "mdi:fan" : "mdi:fan-off", col: speed > 0 ? "var(--ch-teal)" : "var(--ch-dim)",
      v: fanTxt, l: T.fan + (cooking && rec >= 0 ? ` · ${T.recommended} ${rec}` : ""), more: "fan_speed", rx: rxPulse === "fan" })}</div><div class="grid g4">`;
    [1, 2, 3, 4].forEach((s) => {
      const col = s === 4 ? "var(--ch-orange)" : "var(--ch-teal)";
      h += tile({ btn: true, icon: s === 4 ? "mdi:fan-plus" : `mdi:fan-speed-${s}`, col, v: s === 4 ? T.boost : `${T.speed} ${s}`, act: "speed:" + s,
                  on: speed === s, tgt: busy && tSpeed === s && speed !== s });
    });
    h += `</div><div class="grid g3">
      ${tile({ btn: true, icon: "mdi:fan-off", col: "var(--ch-pink)", v: T.stop, act: "speed:0", tgt: busy && tSpeed === 0 && speed !== 0, rx: rxPulse === "stop" })}
      ${tile({ btn: true, icon: "mdi:timer-outline", col: "var(--ch-purple)", v: T.timer, act: "timer", on: left > 0, rx: rxPulse === "timer" })}
      ${tile({ btn: true, icon: "mdi:power-socket-eu", col: "var(--ch-green)", v: T.power, act: "power", on: !!relay && relayOn, dis: !relay })}
    </div></ha-card>`;
    this.shadowRoot.innerHTML = h;
  }

  _click(e) {
    const el = e.target.closest("[data-act],[data-more]"); if (!el || !this._idx) return;
    const hass = this._hass, ids = this._idx.ids;
    const more = el.dataset.more, act = el.dataset.act;
    if (more) {
      const id = more.startsWith("src:") ? this._src(more.slice(4)) : ids[more];
      if (id) this.dispatchEvent(new CustomEvent("hass-more-info", { bubbles: true, composed: true, detail: { entityId: id } }));
      return;
    }
    if (el.classList.contains("dis")) return;
    const sel = (key, i) => {
      const st = this._st(key); const o = st && (st.attributes.options || [])[i];
      if (o !== undefined) hass.callService("select", "select_option", { entity_id: ids[key], option: o });
    };
    const press = (key) => ids[key] && hass.callService("button", "press", { entity_id: ids[key] });
    const [a, n] = act.split(":");
    if (a === "speed") sel("fan_speed", +n);
    else if (a === "bright") sel("light", +n);
    else if (a === "colour") sel("colour", +n);
    else if (a === "light_on") ids.light_on_btn ? press("light_on_btn") : press("key_light");
    else if (a === "light_off") ids.light_off_btn ? press("light_off_btn") : sel("light", 0);
    else if (a === "timer") press("timer10");
    else if (a === "learn_cancel") press("lrn_start");
    else if (a === "power") { const r = this._src("src_hood_switch"); if (r) hass.callService("homeassistant", "toggle", { entity_id: r }); }
  }
}

function tile(o) {
  const cls = ["t", o.big ? "big" : "", o.btn ? "btn" : "", o.on ? "act" : "", o.tgt ? "tgt" : "", o.dis ? "dis" : "", o.rx ? "rxp" : ""].join(" ");
  const data = o.act ? `data-act="${o.act}"` : o.more ? `data-more="${o.more}"` : "";
  return `<div class="${cls}" ${data} style="--ac:${o.col}"><ha-icon icon="${o.icon}" style="color:${o.col}"></ha-icon>` +
    `<div class="v">${esc(o.v || "")}</div>${o.l ? `<div class="l">${esc(o.l)}</div>` : ""}</div>`;
}
function esc(s) { return String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
function fmtW(w) { return isNaN(w) ? "–" : (w >= 100 ? Math.round(w) : Math.round(w * 10) / 10).toString().replace(".", ",") + " W"; }
function mmss(s) { s = Math.round(s); return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`; }

// ---------------------------------------------------------------- editor
class HbhCardEditor extends HTMLElement {
  setConfig(config) { this._config = { ...config }; this._render(); }
  set hass(hass) { const first = !this._hass; this._hass = hass; if (first) this._render(); else this._update(); }

  _render() {
    if (!this._hass || !this._config) return;
    const T = tr(this._hass);
    this.innerHTML = `<div style="display:flex;flex-direction:column;gap:12px">
      <ha-form id="f"></ha-form>
      <div style="font-weight:600;margin-top:4px">${T.sources}</div>
      <div id="src" style="display:flex;flex-direction:column;gap:8px"></div>
      <mwc-button id="apply" raised>${T.apply}</mwc-button></div>`;
    const f = this.querySelector("#f");
    f.hass = this._hass;
    f.schema = [{ name: "device", selector: { device: { integration: "esphome" } } }, { name: "title", selector: { text: {} } },
                { name: "aux1_name", selector: { text: {} } }, { name: "aux2_name", selector: { text: {} } }];
    f.computeLabel = (s) => (s.name === "device" ? T.device : s.name === "title" ? T.card_title : T[s.name]);
    f.data = this._config;
    f.addEventListener("value-changed", (e) => {
      this._config = e.detail.value;
      this.dispatchEvent(new CustomEvent("config-changed", { detail: { config: this._config }, bubbles: true, composed: true }));
      this._update(true);
    });
    this.querySelector("#apply").addEventListener("click", () => {
      const idx = findIndex(this._hass, this._config.device);
      if (idx && idx.ids.apply) this._hass.callService("button", "press", { entity_id: idx.ids.apply });
    });
    this._update(true);
  }

  _update(force) {
    const box = this.querySelector("#src"); if (!box) return;
    const f = this.querySelector("#f"); if (f) f.hass = this._hass;
    const idx = findIndex(this._hass, this._config.device);
    if (!idx) { box.textContent = tr(this._hass).not_found; return; }
    const T = tr(this._hass);
    if (force || box.childElementCount !== SOURCES.length) {
      box.innerHTML = "";
      for (const key of SOURCES) {
        const s = document.createElement("ha-selector");
        s.hass = this._hass;
        s.selector = { entity: {} };
        s.label = T[key];
        s.dataset.key = key;
        s.addEventListener("value-changed", (e) => {
          const id = idx.ids[key]; if (!id) return;
          this._hass.callService("text", "set_value", { entity_id: id, value: e.detail.value || "" });
        });
        box.appendChild(s);
      }
    }
    for (const s of box.children) {
      s.hass = this._hass;
      const id = idx.ids[s.dataset.key];
      const v = id && this._hass.states[id] ? this._hass.states[id].state : "";
      s.value = v && v.includes(".") ? v : "";
    }
  }
}

// ---------------------------------------------------------------- shared base of the extra cards
const CSS2 = CSS + `
  .top { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
  .top > ha-icon { --mdc-icon-size: 26px; color: var(--ch-dim); }
  .top .tt { flex: 1; min-width: 0; }
  .top .s1 { font-size: 10.5px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--ch-dim); opacity: .85; }
  .top .s2 { font-size: 15px; font-weight: 700; color: var(--ch-text); margin-top: 2px; }
  .tg { width: 40px; height: 22px; border-radius: 11px; background: rgba(255,255,255,.12); position: relative; cursor: pointer; flex: none;
        transition: background .2s, box-shadow .2s; }
  .tg::after { content: ""; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: #9399b2; transition: left .2s, background .2s; }
  .tg.on { background: color-mix(in srgb, var(--ch-green) 35%, transparent); box-shadow: 0 0 8px -2px var(--ch-green); }
  .tg.on::after { left: 21px; background: var(--ch-green); }
  .hbar { position: relative; height: 8px; border-radius: 4px; margin: 4px 0 4px; cursor: pointer; }
  .hbar .m { position: absolute; top: -5px; width: 5px; height: 18px; border-radius: 3px; background: #e6e9f5; transform: translateX(-50%);
             box-shadow: 0 0 6px rgba(255,255,255,.6); }
  .scale { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--ch-dim); margin-bottom: 10px; position: relative; height: 14px; }
  .scale span { position: absolute; transform: translateX(-50%); white-space: nowrap; }
  .scale span:nth-child(2) { transform: translateX(-100%); padding-right: 3px; }
  .scale span:nth-child(3) { transform: none; padding-left: 3px; }
  .ah { background: var(--ch-tile); border: 1px solid var(--ch-border); border-radius: 10px; padding: 9px 6px; text-align: center; cursor: pointer; }
  .ah .n { font-size: 18px; font-weight: 800; color: var(--ch-text); } .ah .n small { font-size: 10.5px; font-weight: 600; color: var(--ch-dim); }
  .ah .d { font-size: 10.5px; color: var(--ch-dim); }
  .rows { display: flex; flex-direction: column; gap: 9px; margin: 12px 2px 10px; }
  .row { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--ch-text); cursor: pointer; }
  .row ha-icon { --mdc-icon-size: 18px; color: var(--ch-dim); flex: none; }
  .row ha-icon.ok { color: var(--ch-green); } .row ha-icon.no { color: var(--ch-dim); opacity: .7; }
  .row .k { flex: 1; min-width: 0; } .row .k small { color: var(--ch-dim); }
  .row .val { font-weight: 700; text-align: right; white-space: nowrap; }
  .foot { font-size: 10.5px; color: var(--ch-dim); margin: 2px 2px 0; }
  .seg { display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px; margin-bottom: 6px; }
  .seg div { background: var(--ch-tile); border: 1px solid var(--ch-border); border-radius: 8px; padding: 7px 0; text-align: center;
             font-size: 12.5px; font-weight: 800; color: var(--ch-dim); cursor: pointer; }
  .seg div.on { color: var(--ch-green); border-color: var(--ch-green); box-shadow: 0 0 10px -2px var(--ch-green);
                background: color-mix(in srgb, var(--ch-green) 22%, var(--ch-tile)); }
  .desc { font-size: 11px; color: var(--ch-dim); margin: 0 2px 4px; }
  .more { margin-top: 10px; background: var(--ch-tile); border: 1px solid var(--ch-border); border-radius: 10px; padding: 8px; text-align: center;
          font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .04em; cursor: pointer; color: var(--ch-text); }
  .more ha-icon { --mdc-icon-size: 16px; vertical-align: -3px; }
`;

class HbhBase extends HTMLElement {
  static getStubConfig() { return {}; }
  setConfig(config) { this._config = config || {}; this._sig = null; if (this._hass) this._render(); }
  connectedCallback() { this._tick = setInterval(() => this._render(), 15000); }
  disconnectedCallback() { clearInterval(this._tick); }
  set hass(hass) {
    this._hass = hass;
    const n = Object.keys(hass.entities || {}).length;
    if (!this._idx || this._idxAt !== n) { this._idx = findIndex(hass, this._config && this._config.device); this._idxAt = n; }
    this._render();
  }
  _st(key) { const id = this._idx && this._idx.ids[key]; return id ? this._hass.states[id] : undefined; }
  _v(key) { const s = this._st(key); return s ? s.state : undefined; }
  _num(key) { const v = parseFloat(this._v(key)); return isNaN(v) ? NaN : v; }
  _src(key) { const v = this._v(key); return v && v.includes(".") ? v.split(":")[0] : null; }
  _on(key) { return this._v(key) === "on"; }
  _hm(key) { const v = this._v(key); return v && v.includes(":") ? v.slice(0, 5).replace(/^0(\d)/, "$1") : "–"; }
  _changed(keys) {
    const hass = this._hass, idx = this._idx;
    const sig = (idx ? idx.device : "-") + hass.language + (this._open ? 1 : 0) + new Date().getMinutes() + "|" +
      (idx ? keys.map((k) => this._v(k)).join("|") + "|" + SOURCES.map((k) => { const e = this._src(k); return e && hass.states[e] ? hass.states[e].state : ""; }).join("|") : "");
    if (sig === this._sig) return false;
    this._sig = sig; return true;
  }
  _shell() {
    if (!this.shadowRoot) { this.attachShadow({ mode: "open" }); this.shadowRoot.addEventListener("click", (e) => this._click(e)); }
  }
  _click(e) {
    const el = e.target.closest("[data-act],[data-more]"); if (!el || !this._idx) return;
    const hass = this._hass, ids = this._idx.ids;
    if (el.dataset.more) {
      const m = el.dataset.more;
      const id = m.startsWith("src:") ? this._src(m.slice(4)) : ids[m];
      if (id) this.dispatchEvent(new CustomEvent("hass-more-info", { bubbles: true, composed: true, detail: { entityId: id } }));
      return;
    }
    const [a, n] = el.dataset.act.split(":");
    if (a === "toggle" && ids[n]) hass.callService("switch", "toggle", { entity_id: ids[n] });
    else if (a === "profile") {
      const st = this._st("profile"); const o = st && (st.attributes.options || [])[+n];
      if (o !== undefined) hass.callService("select", "select_option", { entity_id: ids.profile, option: o });
    } else if (a === "open") { this._open = !this._open; this._sig = null; this._render(); }
  }
  _name(key) {  // entity name in the language of HA (settings list), else without the device name
    const st = this._st(key); if (!st) return key;
    const tr_ = NAMES[(KEYS[key] || [])[1]];
    if (tr_ && tr_[langOf(this._hass)]) return tr_[langOf(this._hass)];
    const dev = this._hass.devices && this._idx && this._hass.devices[this._idx.device];
    const dn = dev ? (dev.name_by_user || dev.name || "") : "";
    const fn = st.attributes.friendly_name || key;
    return dn && fn.startsWith(dn + " ") ? fn.slice(dn.length + 1) : fn;
  }
  _fmt(key) {
    const st = this._st(key); if (!st) return "–";
    const u = st.attributes.unit_of_measurement || "";
    if (st.entity_id.startsWith("switch.")) return st.state === "on" ? tr(this._hass).yes : tr(this._hass).no;
    if (st.entity_id.startsWith("time.")) return this._hm(key);
    if (st.entity_id.startsWith("button.")) return "›";
    if (key === "cal_state" || key === "lrn_state") return locState(this._hass, st.state);
    const v = parseFloat(st.state);
    return isNaN(v) ? st.state : `${String(Math.round(v * 10) / 10).replace(".", ",")}${u ? " " + u : ""}`;
  }
}
const row = (o) => `<div class="row" ${o.act ? `data-act="${o.act}"` : o.more ? `data-more="${o.more}"` : ""}>` +
  `<ha-icon icon="${o.icon}" class="${o.cls || ""}"></ha-icon><div class="k">${o.k}</div><div class="val">${o.val}</div></div>`;
const toggle = (key, on) => `<div class="tg ${on ? "on" : ""}" data-act="toggle:${key}"></div>`;
const dec = (v, d = 1) => (isNaN(v) ? "–" : (Math.round(v * 10 ** d) / 10 ** d).toFixed(d).replace(".", ","));

// ---------------------------------------------------------------- drying card
class HbhDryingCard extends HbhBase {
  static getConfigElement() { return document.createElement("hbh-card-editor"); }
  getCardSize() { return 6; }
  _render() {
    const hass = this._hass; if (!hass || !this._config) return;
    this._shell();
    const keys = ["dry_sw", "dry_state", "drying", "room_ah", "out_ah", "room_rh", "room_t", "out_t", "out_rh", "dry_start", "dry_stop",
                  "dry_diff", "dry_max", "dry_tmin", "dry_from", "dry_to", "speed", "night_sw", "night_at"];
    if (!this._changed(keys)) return;
    const T = tr(hass), idx = this._idx;
    let h = `<style>${CSS2}</style><ha-card>`;
    if (!idx) { this.shadowRoot.innerHTML = h + `<div class="nf">${T.not_found}</div></ha-card>`; return; }
    const on = this._on("dry_sw"), drying = this._on("drying");
    const rh = this._num("room_rh"), start = this._num("dry_start"), stop = this._num("dry_stop");
    const rah = this._num("room_ah"), oah = this._num("out_ah"), diff = this._num("dry_diff");
    const tout = this._num("out_t"), tmin = this._num("dry_tmin"), speed = this._num("speed");
    const lo = 40, hi = 80, pos = (v) => Math.max(0, Math.min(100, ((v - lo) / (hi - lo)) * 100));
    const now = new Date(), nm = now.getHours() * 60 + now.getMinutes();
    const tm = (k) => { const v = this._v(k); if (!v || !v.includes(":")) return NaN; const [a, b] = v.split(":"); return +a * 60 + +b; };
    const f = tm("dry_from"), t = tm("dry_to");
    const inWin = isNaN(f) || isNaN(t) ? false : f <= t ? nm >= f && nm < t : nm >= f || nm < t;
    const hasDry = !!this._st("dry_start");
    h += `<div class="top"><ha-icon icon="${drying ? "mdi:fan" : "mdi:timer-sand"}" style="${drying ? "color:var(--ch-teal)" : ""}"></ha-icon>
      <div class="tt" data-more="dry_state"><div class="s1">${esc(this._config.title || T.dry_title)}</div>
      ${hasDry ? `<div class="s2">${esc(cap(locState(hass, this._v("dry_state") || "")))}</div>` : ""}</div>${hasDry ? toggle("dry_sw", on) : ""}</div>`;
    if (!hasDry) { this.shadowRoot.innerHTML = h + `<div class="foot">${T.dry_missing}</div></ha-card>`; return; }
    const noSrc = isNaN(rh) || isNaN(rah) || isNaN(oah);
    // humidity bar: below stop = dry (green), stop..start = between (yellow), above start = humid (blue)
    if (!isNaN(stop) && !isNaN(start)) {
      h += `<div class="hbar" data-more="room_rh" style="background:linear-gradient(90deg,
          #2f7d54 0%, #2f7d54 ${pos(stop)}%, #8a7a2a ${pos(stop)}%, #8a7a2a ${pos(start)}%, #1f6f8b ${pos(start)}%, #1f6f8b 100%)">
          ${isNaN(rh) ? "" : `<div class="m" style="left:${pos(rh)}%"></div>`}</div>
        <div class="scale"><span style="left:0;transform:none">${lo} %</span><span style="left:${pos(stop)}%">stop ${dec(stop, 0)} %</span>
          <span style="left:${pos(start)}%">start ${dec(start, 0)} %</span><span style="left:auto;right:0;transform:none">${hi} %</span></div>`;
    }
    if (noSrc) h += `<div class="foot" style="margin-bottom:10px">${T.dry_nosrc}</div>`;
    h += `<div class="grid g2">
      <div class="ah" data-more="room_ah"><div class="n">${dec(rah)} <small>g/m³</small></div>
        <div class="d">${T.kitchen} · ${dec(rh, 0)} % · ${dec(this._num("room_t"))} °C</div></div>
      <div class="ah" data-more="out_ah"><div class="n">${dec(oah)} <small>g/m³</small></div>
        <div class="d">${T.outside} · ${dec(this._num("out_rh"), 0)} % · ${dec(tout)} °C</div></div></div>`;
    const ok = (b) => (b ? { icon: "mdi:check-circle", cls: "ok" } : { icon: "mdi:close-circle-outline", cls: "no" });
    const hhmm = `${now.getHours()}:${String(now.getMinutes()).padStart(2, "0")}`;
    h += `<div class="rows">
      ${row({ ...ok(rh > start), k: fill(T.cond_rh, { x: dec(start, 0) }), val: `${dec(rh, 0)} %`, more: "room_rh" })}
      ${row({ ...ok(rah - oah >= diff), k: fill(T.cond_ah, { x: dec(diff) }), val: `${dec(rah - oah)} g/m³`, more: "dry_diff" })}
      ${row({ ...ok(inWin), k: fill(T.cond_hours, { a: this._hm("dry_from").replace(/:00$/, ""), b: this._hm("dry_to").replace(/:00$/, "") }), val: hhmm, more: "dry_from" })}
      ${row({ ...ok(tout > tmin), k: fill(T.cond_tout, { x: dec(tmin, 0) }), val: `${dec(tout)} °C`, more: "out_t" })}
      ${row({ ...ok(speed === 0 || drying), k: T.cond_stopped, val: `${T.prof_fan} ${isNaN(speed) ? "–" : speed}`, more: "speed" })}
    </div>`;
    let foot = fill(T.dry_foot, { stop: dec(stop, 0), max: dec(this._num("dry_max"), 0) });
    if (this._on("night_sw")) foot += " · " + fill(T.night, { t: this._hm("night_at") });
    h += `<div class="foot" data-more="dry_max">${esc(foot)}</div></ha-card>`;
    this.shadowRoot.innerHTML = h;
  }
}

// ---------------------------------------------------------------- hob automation card
class HbhAutomationCard extends HbhBase {
  static getConfigElement() { return document.createElement("hbh-card-editor"); }
  getCardSize() { return 8; }
  _render() {
    const hass = this._hass; if (!hass || !this._config) return;
    this._shell();
    const keys = ["auto", "mode", "profile", "hob_avg", "cooking", "hob_on", "aux1_on", "aux2_on", "aux1_sw", "aux2_sw", "recommended", "speed",
                  "light_on", "brightness", "auto_light", "runon", "p2", "p3", "runon_aux", "light_after", "alarm_sw", "alarm_after",
                  "auto_colour", "cool_from", "warm_from", "night_sw", "night_at", "aux1_thr", "aux2_thr", "last_energy", "last_time",
                  "filter_usage", "filter_due", "filter_hours", "cal_state", "power_table", "lrn_state"];
    if (!this._changed(keys)) return;
    const T = tr(hass), idx = this._idx;
    let h = `<style>${CSS2}</style><ha-card>`;
    if (!idx) { this.shadowRoot.innerHTML = h + `<div class="nf">${T.not_found}</div></ha-card>`; return; }
    const profSt = this._st("profile"), opts = profSt ? profSt.attributes.options || [] : [];
    const pi = profSt ? opts.indexOf(profSt.state) : -1;
    const cooking = this._on("cooking");
    h += `<div class="top"><ha-icon icon="${cooking ? "mdi:pot-steam" : "mdi:timer-sand"}" style="${cooking ? "color:var(--ch-orange)" : ""}"></ha-icon>
      <div class="tt" data-more="mode"><div class="s1">${esc(this._config.title || T.auto_title)}${profSt ? " · " + esc(profSt.state) : ""}</div>
      <div class="s2">${esc(cap(locState(hass, this._v("mode") || "")))}</div></div>${toggle("auto", this._on("auto"))}</div>`;
    h += `<div class="seg">${opts.map((o, i) => `<div class="${i === pi ? "on" : ""}" data-act="profile:${i}">${esc(o)}</div>`).join("")}</div>`;
    if (pi >= 0) {
      const P = PROFILES[pi] || PROFILES[5];
      const d = pi === 0 ? `H0 – ${T.prof_h0}` : pi === 1 ? `H1 – ${T.prof_h1}` :
        `${opts[pi]}${pi === 5 ? " – " + T.default_ : ""}. ${T.prof_light} · ${T.prof_fan}: ${T.lv1} ${P[0]} · ${T.lv2} ${P[1]} · ${T.lv3} ${P[2]}`;
      h += `<div class="desc">${esc(d)}</div>`;
    }
    const kw = (w) => (isNaN(w) ? "–" : dec(Math.max(0, w) / 1000, 1) + " kW");
    const hobState = cooking ? T.cooking : this._on("hob_on") ? T.on : T.off;
    const srcVal = (k) => { const e = this._src(k); const st = e && hass.states[e]; if (!st) return "";
      const u = st.attributes.unit_of_measurement; const v = parseFloat(st.state);
      return isNaN(v) ? st.state : `${Math.round(v * 10) / 10}${u ? " " + u : ""}`; };
    const n1 = this._config.aux1_name || T.source1, n2 = this._config.aux2_name || T.source2;
    const speed = this._num("speed"), lightOn = this._on("light_on"), br = this._num("brightness");
    const hoodNow = `${speed === 4 ? T.boost.toLowerCase() : T.prof_fan + " " + (isNaN(speed) ? "–" : speed)} · ${lightOn ? (isNaN(br) ? T.light_short : br + " %") : T.light_off_w}`;
    const rows = [
      row({ icon: "mdi:stove", k: T.hob_avg_row, val: `${kw(this._num("hob_avg"))} · ${hobState}`, more: "hob_avg" }),
    ];
    if (this._src("src_aux1")) rows.push(row({ icon: "mdi:chef-hat", k: esc(n1), val: `${this._on("aux1_on") ? T.working : T.idle}${srcVal("src_aux1") ? " · " + srcVal("src_aux1") : ""}`, more: "aux1_on" }));
    if (this._src("src_aux2")) rows.push(row({ icon: "mdi:kettle-steam", k: esc(n2), val: `${this._on("aux2_on") ? T.working : T.idle}${srcVal("src_aux2") ? " · " + srcVal("src_aux2") : ""}`, more: "aux2_on" }));
    rows.push(row({ icon: "mdi:fan-auto", k: T.rec_row, val: isNaN(this._num("recommended")) ? "–" : this._num("recommended"), more: "recommended" }));
    rows.push(row({ icon: "mdi:range-hood", k: T.hood_now, val: hoodNow, more: "speed" }));
    if (this._src("src_aux1")) rows.push(row({ icon: "mdi:chef-hat", k: `${T.react} ${esc(n1)} <small>(&gt; ${this._fmt("aux1_thr")})</small>`, val: toggle("aux1_sw", this._on("aux1_sw")) }));
    if (this._src("src_aux2")) rows.push(row({ icon: "mdi:kettle-steam", k: `${T.react} ${esc(n2)} <small>(${T.runon_short} ${this._fmt("runon_aux")})</small>`, val: toggle("aux2_sw", this._on("aux2_sw")) }));
    rows.push(row({ icon: "mdi:lightbulb-auto", k: T.auto_light_row, val: toggle("auto_light", this._on("auto_light")) }));
    rows.push(row({ icon: "mdi:timer-sand", k: T.runon_row, val: this._fmt("runon"), more: "runon" }));
    if (this._st("last_energy") && !isNaN(this._num("last_energy")))
      rows.push(row({ icon: "mdi:pot-steam", k: T.last_cooking, val: `${dec(this._num("last_energy"), 2)} kWh · ${dec(this._num("last_time"), 0)} min`, more: "last_energy" }));
    if (this._st("filter_usage"))
      rows.push(row({ icon: "mdi:air-filter", cls: this._on("filter_due") ? "" : "", k: T.filter_row, val: `${dec(this._num("filter_usage"), 0)} %`, more: "filter_usage" }));
    h += `<div class="rows">${rows.join("")}</div>`;
    h += `<div class="foot" data-more="p2">${esc(fill(T.levels, { a: dec(this._num("p2") / 1000), b: dec(this._num("p3") / 1000) }))}</div>`;
    h += `<div class="more" data-act="open"><ha-icon icon="mdi:tune-variant"></ha-icon> ${T.settings} ${this._open ? "▴" : "▾"}</div>`;
    if (this._open) {
      const set = ["p2", "p3", "runon", "runon_aux", "light_after", "hob_on_thr", "aux1_thr", "aux2_thr", "alarm_sw", "alarm_after", "auto_colour",
                   "cool_from", "warm_from", "night_sw", "night_at", "filter_hours", "filter_clean", "cal_state", "power_table",
                   "cal_start", "cal_reset", "lrn_state", "lrn_start", "lrn_reset"].filter((k) => this._st(k));
      h += `<div class="rows">${set.map((k) => row({ icon: (this._st(k).attributes.icon || "mdi:cog"), k: esc(this._name(k)), val: this._fmt(k), more: k })).join("")}</div>`;
    }
    this.shadowRoot.innerHTML = h + `</ha-card>`;
  }
}
function cap(s) { return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }

